185	// 编码合法但转账格式错误的动作照常登记，由执行操作按现有规则拒绝。
186	func TestRegisterPreservesValidText(t *testing.T) {
187		store, _ := openTempStore(t, 1000)
188		defer store.Close()
189	
190		id := "提案-�-😀"
191		actions := []string{
192			"transfer:账户:100",
193			"transfer:smi�le-😀:50",
194			`transfer:back\uD800slash:1`, // 反斜杠 + 普通字母的字面文本
195			"not-a-transfer",             // 编码合法但格式错误：登记时不拒绝
196		}
197		mustRegister(t, store, id, 100, actions...)
198	
199		// 相同内容的合法重试仍返回已有登记。
200		existed, err := store.Register(id, 100, actions)

