			// 原文件保持原样，不被重算结果覆盖。
			if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
				t.Fatalf("corrupt file was modified")
			}
		})
	}
}

// TestRegisteredAndVotedProposalsTransferIdentically：相同动作与起始余额下，
// 登记来源与投票通过来源的提案产生相同的资金变动与逐笔凭据，且已执行
// 提案再次执行仍返回首次凭据。
func TestRegisteredAndVotedProposalsTransferIdentically(t *testing.T) {
	actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}

	registered, _ := openTempStore(t, 1000)
	defer registered.Close()
	mustRegister(t, registered, "gip-r", 0, actions...)
	rr, err := registered.Execute("gip-r", 0)
	if err != nil {
		t.Fatal(err)
	}

	voted, _ := openTempStore(t, 1000)
	defer voted.Close()
	in := baseVoteInput("gip-v")
	in.Actions = actions
	in.StartAt, in.Deadline, in.TimelockEnd = 0, 1, 1
	mustCreateVote(t, voted, in)
	if _, err := voted.CastVote("gip-v", "alice", true, 0); err != nil {
		t.Fatal(err)
	}
	if _, err := voted.TallyVote("gip-v", 1); err != nil {
		t.Fatal(err)
	}
	vr, err := voted.Execute("gip-v", 1)
	if err != nil {
		t.Fatal(err)
	}

	if len(rr.Actions) != len(vr.Actions) {
		t.Fatalf("receipt action counts differ: %d vs %d", len(rr.Actions), len(vr.Actions))
	}
	for i := range rr.Actions {
		// 两个来源的凭据只有动作原文（编号相同）与双方前后余额可比。
		ra, va := rr.Actions[i], vr.Actions[i]
		if ra.Action != va.Action || !reflect.DeepEqual(ra.Treasury, va.Treasury) ||
			!reflect.DeepEqual(ra.Recipient, va.Recipient) || ra.Index != va.Index {
			t.Fatalf("action %d differs by source:\nregistered=%+v\nvoted=%+v", i, ra, va)
		}
	}
	for _, pair := range []struct {
		name    string
		store   *Store
		receipt *Receipt
		id      string
	}{
		{"registered", registered, rr, "gip-r"},
		{"voted", voted, vr, "gip-v"},
	} {
		if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
			t.Fatalf("%s treasury=%d, want 600", pair.name, bal)
		}
		if bal, _ := pair.store.Balance("audits"); bal != 350 {
			t.Fatalf("%s audits=%d, want 350", pair.name, bal)
		}
		if bal, _ := pair.store.Balance("legal"); bal != 50 {
			t.Fatalf("%s legal=%d, want 50", pair.name, bal)
		}
		// 再次执行返回首次凭据，不产生二次资金变动。
		again, err := pair.store.Execute(pair.id, 99999)
		if err != nil {
			t.Fatalf("%s re-execute: %v", pair.name, err)

		t.Fatal(err)
	}
	good, err = os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return dir, path, good
}

// mutateReceipts 以结构化改写构造缺损变体：fn 直接操作 receipts 数组。
func mutateReceipts(t *testing.T, good []byte, fn func(receipts []any)) []byte {
	t.Helper()
	var root map[string]any
	if err := json.Unmarshal(good, &root); err != nil {
		t.Fatal(err)
	}
	receipts := root["receipts"].([]any)
	fn(receipts)
	raw, err := json.MarshalIndent(root, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	return append(raw, '\n')
}

// TestReceiptOrderAndIndexStrictlyValidated：每份执行凭据的 order 与每项动作的
// index 都必须明确保存为 int64 范围内的非负整数，且分别等于凭据位置、动作位置。
// 缺失、null、字符串、布尔、小数、指数写法、超界或位置不符都判整份状态损坏；
// 排在第一项不能把缺失补成 0，资金变动与原文可重放一致也不宽免。
func TestReceiptOrderAndIndexStrictlyValidated(t *testing.T) {
	dir, _, good := buildOrderIndexFixture(t)

	// 基线完整可读：显式写出的 0 是有效序号；同一账户连续两项动作分别保留。
	t.Run("baseline explicit zero readable", func(t *testing.T) {
		base := filepath.Join(dir, "base.json")
		if err := os.WriteFile(base, good, 0o600); err != nil {
			t.Fatal(err)
		}
		s, err := Open(base)
		if err != nil {
			t.Fatalf("reopen baseline: %v", err)
		}
		defer s.Close()
		receipts, err := s.Receipts()
		if err != nil || len(receipts) != 2 {
			t.Fatalf("receipts=%v err=%v", receipts, err)
		}
		r0, r1 := receipts[0], receipts[1]
		if r0.ProposalID != "gip-a" || r0.Order != 0 ||
			r1.ProposalID != "gip-v" || r1.Order != 1 {
			t.Fatalf("receipt order not read as saved: %s=%d %s=%d",
				r0.ProposalID, r0.Order, r1.ProposalID, r1.Order)
		}
		if len(r0.Actions) != 2 || r0.Actions[0].Index != 0 || r0.Actions[1].Index != 1 {
			t.Fatalf("action indexes not read as saved: %+v", r0.Actions)
		}
		// 同一收款账户连续出现：仍是两条独立动作记录，顺序不变、不合并。
		if r0.Actions[0].Action != "transfer:acct:100" || r0.Actions[1].Action != "transfer:acct:50" {
			t.Fatalf("consecutive same-recipient actions altered: %+v", r0.Actions)
		}
		if bal, _ := s.Balance("acct"); bal != 150 {
			t.Fatalf("acct balance=%d, want 150", bal)
		}
		one, ok, err := s.Receipt("gip-a")
		if err != nil || !ok || one.Order != 0 || one.Actions[0].Index != 0 {
			t.Fatalf("Receipt(gip-a)=%+v ok=%v err=%v", one, ok, err)
		}
		// 查询 JSON 仍输出明确保存的 0。
