// TestEmptyActionReceiptCorruptsWholeState：任务主例。空动作凭据让整份
// 状态文件打开失败——错误指出提案编号并说明凭据没有动作；余额、提案与
// 凭据查询都没有部分结果，对该提案执行也不能当作已完成重试返回成功；
// init 不覆盖损坏文件；失败后原文件逐字节保留。
func TestEmptyActionReceiptCorruptsWholeState(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "treasury.json")
	doc := emptyReceiptTaskDoc()
	writeStateDoc(t, path, doc)
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	s, err := Open(path)
	if !errors.Is(err, ErrStateCorrupt) {
		if s != nil {
			s.Close()
		}
		t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
	}
	for _, want := range []string{`"gip-empty"`, "has no actions"} {
		if !strings.Contains(err.Error(), want) {
			t.Fatalf("error %q must contain %q", err.Error(), want)
		}
	}

	// 打开失败即没有可用句柄：所有查询都不可能给出部分结果。再用独立句柄
	// 验证每类操作在读取时都按状态损坏失败。
	fresh, ferr := Open(path)
	if ferr == nil {
		// 新鲜句柄同样打不开；若意外成功，用它逐一验证操作后关闭。
		defer fresh.Close()
	}
	for _, op := range []struct {
		name string
		run  func() error
	}{
		{"BalanceSnapshot", func() error { _, e := fresh.BalanceSnapshot(); return e }},
		{"TreasuryBalance", func() error { _, e := fresh.TreasuryBalance(); return e }},
		{"Balance", func() error { _, e := fresh.Balance("anyone"); return e }},
		{"Balances", func() error { _, e := fresh.Balances(); return e }},
		{"Proposal", func() error { _, _, e := fresh.Proposal("gip-empty"); return e }},
		{"Proposals", func() error { _, e := fresh.Proposals(); return e }},
		{"ProposalsSnapshot", func() error { _, e := fresh.ProposalsSnapshot(); return e }},
		{"Receipt", func() error { _, _, e := fresh.Receipt("gip-empty"); return e }},
		{"Receipts", func() error { _, e := fresh.Receipts(); return e }},
		{"Register", func() error { _, e := fresh.Register("other", 0, []string{"transfer:a:1"}); return e }},
	} {
		// fresh 仅在意外成功打开时非 nil；正常路径下直接重新打开做一次操作。
		var store *Store
		if ferr == nil {
			store = fresh
		} else {
			st, oerr := Open(path)
			if oerr == nil {
				t.Fatalf("%s: second Open unexpectedly succeeded", op.name)
			}
			if !errors.Is(oerr, ErrStateCorrupt) {
				t.Fatalf("%s: second Open err=%v, want ErrStateCorrupt", op.name, oerr)
			}
			continue
		}
		if err := op.run(); !errors.Is(err, ErrStateCorrupt) {
			t.Fatalf("%s on corrupt state err=%v, want ErrStateCorrupt", op.name, err)
		}
		_ = store
	}

	// 对损坏文件中的 executed 提案执行：不能当作“已完成重试”返回成功凭据，
	// 必须按状态损坏拒绝。
	execStore, execErr := Open(path)
	if execErr == nil {
		defer execStore.Close()
		rcpt, eerr := execStore.Execute("gip-empty", 0)
		if !errors.Is(eerr, ErrStateCorrupt) || rcpt != nil {
			t.Fatalf("Execute on empty-receipt state rcpt=%+v err=%v, want nil + ErrStateCorrupt", rcpt, eerr)
		}
	}

	// init 不得重建或覆盖损坏文件。
	if _, err := InitTreasury(path, 0); !errors.Is(err, ErrTreasuryAlreadyInit) {
		t.Fatalf("InitTreasury over corrupt file err=%v, want ErrTreasuryAlreadyInit", err)
	}

	// 失败保留原文件：不删除空凭据、不补造转账、不把提案改回 passed。
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(after) != string(before) {
		t.Fatalf("corrupt file was modified")
	}
}

